        if len(flow_id) > MAX_PACKET_ID_CODEPOINTS:
            raise PacketError(
                "packet.flow_id exceeds %d code points"
                % MAX_PACKET_ID_CODEPOINTS
            )
        resolved.append((at, packet_id, ttl, flow_id))
    return resolved

